INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (133, 'hotFormulasModeloBase', 'Mount de Formulas do Modelo em 1 ida (DRIVER,CONTAS,LINHAS,VINCULOS). Param: driverId.', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''DESCRICAO'',t.DESCRICAO,''COR'',t.COR,''ATIVO'',t.ATIVO,''CRIADO_EM'',t.CRIADO_EM,''TIPO_DRIVER'',t.TIPO_DRIVER,''ORIGEM'',t.ORIGEM)) FROM DRIVERS t WHERE t.ID = {{driverId}}),JSON_ARRAY()) AS DRIVER,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',c.ID,''CODIGO'',c.CODIGO,''NOME'',c.NOME)) FROM CONTA_CONTABIL c),JSON_ARRAY()) AS CONTAS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''DRIVER_ID'',t.DRIVER_ID,''CONTA_ID'',t.CONTA_ID,''FORMULA'',t.FORMULA,''DESCRICAO'',t.DESCRICAO,''TIPO'',t.TIPO,''ORDEM'',t.ORDEM,''NOME_CUSTOM'',t.NOME_CUSTOM,''LABEL'',t.LABEL,''ESCONDER'',t.ESCONDER,''NEGRITO'',t.NEGRITO,''FORMATO'',t.FORMATO)) FROM DRIVER_FORMULA t WHERE t.DRIVER_ID = {{driverId}}),JSON_ARRAY()) AS LINHAS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',cd.CONTA_ID)) FROM CONTA_DRIVER cd WHERE cd.DRIVER_ID = {{driverId}}),JSON_ARRAY()) AS VINCULOS', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
